import { capitalize, isString } from 'lodash-es';

import { useHoneycombBaseScale } from './use-honeycomb-base-scale.js';
import { HoneycombTileData } from '../types/honeycomb.js';
import { TileColorMetadata } from '../types/rendering.js';

export const useBuildColorMetadata = (data: HoneycombTileData[]) => {
  const scale = useHoneycombBaseScale();
  const honeycombDataWithColoringMetadata: WeakMap<
    HoneycombTileData,
    TileColorMetadata
  > = new WeakMap();

  for (let i = 0; i < data.length; i++) {
    const index = i;
    const { value } = data[i];
    const parsedData = isString(value) ? capitalize(value) : value;
    // @ts-expect-error - Assertion that scale and data type match are already done.
    const baseColor = scale(parsedData);

    const tileColorData = {
      index,
      baseColor,
    };

    honeycombDataWithColoringMetadata.set(data[i], tileColorData);
  }

  return honeycombDataWithColoringMetadata;
};
